insert into public.songs (slug, title, tag, category_label, tune, blocks, sort_order)
values
  ('campfires-burning', 'Campfires Burning', 'round', 'Opener · round', 'Tune: “Frère Jacques” · sing it as a three-part round', '[{"type": "verse", "text": "Campfires burning, campfires burning,\nDraw nearer, draw nearer,\nIn the glowing, in the glowing,\nCome sing and be merry."}, {"type": "note", "text": "Split into three groups. The second starts when the first reaches “draw nearer”, the third when the second does."}]'::jsonb, 1),
  ('ging-gang-goolie', 'Ging Gang Goolie', 'loud', 'Loud', 'Tune: traditional — the oldest Scout campfire chant there is', '[{"type": "verse", "text": "Ging gang gooli gooli gooli gooli watcha,\nGing gang goo, ging gang goo.\nGing gang gooli gooli gooli gooli watcha,\nGing gang goo, ging gang goo."}, {"type": "verse", "text": "Heyla, heyla sheyla, heyla sheyla, heyla ho,\nHeyla, heyla sheyla, heyla sheyla, heyla ho."}, {"type": "verse", "text": "Shalli-walli, shalli-walli, shalli-walli, shalli-walli,\nOompa, oompa, oompa, oompa."}, {"type": "note", "text": "It means nothing at all — that''s the point. Once through slowly, then as fast as you can manage."}]'::jsonb, 2),
  ('there-aint-no-flies-on-us', 'There Ain''t No Flies On Us', 'loud', 'Loud', 'Tune: “The Girl I Left Behind Me” · point at the other patrol', '[{"type": "verse", "text": "There ain''t no flies on us,\nThere ain''t no flies on us.\nThere might be flies on some of you guys,\nBut there ain''t no flies on us!"}, {"type": "note", "text": "Patrol against patrol — swap “you guys” for the other mob''s name."}]'::jsonb, 3),
  ('singing-in-the-rain', 'Singing In The Rain', 'actions', 'Actions', 'Tune: “Singin'' in the Rain” · add one action each time through', '[{"type": "verse", "text": "We''re singing in the rain, just singing in the rain,\nWhat a glorious feeling, we''re happy again.\n_Hang about!_"}, {"type": "verse", "text": "Thumbs up! _(everyone echoes)_\nA-root-ta-ta, root-ta-ta, root-ta-ta-TA!"}, {"type": "grid", "heading": "Add each in turn, keeping the last", "items": ["Thumbs up", "Arms out", "Elbows in", "Knees bent", "Knees together", "Toes together", "Bottom out", "Chest out", "Head back", "Tongue out"]}, {"type": "note", "text": "By the last verse nobody can sing a word — that''s when you stop."}]'::jsonb, 4),
  ('boom-chicka-boom', 'Boom Chicka Boom', 'echo', 'Echo', 'Spoken, not sung — the leader calls each line, everyone repeats it', '[{"type": "verse", "text": "I said a-boom-chicka-boom,\nI said a-boom-chicka-boom,\nI said a-boom-chicka-rocka-chicka-rocka-chicka-boom.\nUh-huh! Oh yeah!\nOne more time, _(name a)_ style!"}, {"type": "box", "heading": "Styles to call", "items": ["**Flower:** I said a bloom chicka bloom, I said a bloom chicka blossom smell those flowers chicka bloom.", "**Race car:** I said a vroom shifta vroom, I said a vroom shifta grind-a shifta grind-a shifta vroom.", "**Astronaut:** I said a moon shoot the moon, I said a moon blast-me shoot-me blast-me shoot-me-to-the-moon.", "**Fire:** I said an OUCH chicka OUCH, I said an OUCH burnt my finger in the fire chicka OUCH."]}, {"type": "note", "text": "Then invent your own: underwater, opera, slow-motion, Cub style."}]'::jsonb, 5),
  ('alice-the-camel', 'Alice The Camel', 'actions', 'Actions', 'Tune: traditional · count down from five, bump hips on every “boom”', '[{"type": "verse", "text": "Alice the camel has five humps,\nAlice the camel has five humps,\nAlice the camel has five humps,\nSo go, Alice, go — boom, boom, boom!"}, {"type": "note", "text": "Repeat with four humps, three, two, one…"}, {"type": "verse", "text": "Alice the camel has no humps,\nAlice the camel has no humps,\nAlice the camel has no humps,\n''Cos Alice is a horse!"}]'::jsonb, 6),
  ('meat-balls-song', 'Meat Balls Song', 'loud', 'Story song', 'Tune: “On Top of Old Smoky”', '[{"type": "verse", "text": "On top of spaghetti,\nAll covered with cheese,\nI lost my poor meatball,\nWhen somebody sneezed."}, {"type": "verse", "text": "It rolled off the table,\nAnd on to the floor,\nAnd then my poor meatball,\nRolled out of the door."}, {"type": "verse", "text": "It rolled in the garden,\nAnd under a bush,\nAnd then my poor meatball,\nWas nothing but mush."}, {"type": "verse", "text": "The mush was as tasty,\nAs tasty could be,\nAnd then the next summer,\nIt grew into a tree."}, {"type": "verse", "text": "The tree was all covered,\nAll covered with moss,\nAnd on it grew meatballs,\nAnd tomato sauce."}, {"type": "verse", "text": "So if you eat spaghetti,\nAll covered with cheese,\nHold on to your meatball,\nWhenever you sneeze!"}]'::jsonb, 7),
  ('kum-ba-yah', 'Kum Ba Yah', 'quiet', 'Quiet', 'Tune: traditional spiritual · slow, soft, one verse at a time', '[{"type": "verse", "text": "Kum ba yah, my Lord, kum ba yah,\nKum ba yah, my Lord, kum ba yah,\nKum ba yah, my Lord, kum ba yah,\nO Lord, kum ba yah."}, {"type": "verse", "text": "Someone''s crying, Lord, kum ba yah… _(×3)_\nO Lord, kum ba yah."}, {"type": "verse", "text": "Someone''s singing, Lord, kum ba yah… _(×3)_\nO Lord, kum ba yah."}, {"type": "verse", "text": "Someone''s praying, Lord, kum ba yah… _(×3)_\nO Lord, kum ba yah."}]'::jsonb, 8),
  ('grand-old-duke-of-york', 'Grand Old Duke Of York', 'actions', 'Actions', 'Tune: traditional marching song · stand on “up”, sit on “down”', '[{"type": "verse", "text": "Oh, the Grand old Duke of York,\nHe had ten thousand men,\nHe marched them up to the top of the hill,\nAnd he marched them down again."}, {"type": "verse", "text": "And when they were up, they were up,\nAnd when they were down, they were down,\nAnd when they were only half way up,\nThey were neither up nor down."}, {"type": "note", "text": "Faster each time round until everyone collapses."}]'::jsonb, 9),
  ('bingo', 'Bingo', 'actions', 'Actions', 'Tune: traditional · one more clap replaces one more letter', '[{"type": "verse", "text": "There was a dog in my back yard,\nAnd Bingo was his name-o.\nB—I—N—G—O,\nB—I—N—G—O,\nB—I—N—G—O,\nAnd Bingo was his name-o."}, {"type": "box", "heading": "How it builds", "items": ["Round 2 — _clap_ I N G O", "Round 3 — _clap clap_ N G O", "Round 4 — _clap clap clap_ G O", "Right through to five claps and no letters at all."]}]'::jsonb, 10),
  ('a-pizza-hut', 'A Pizza Hut', 'actions', 'Actions', 'Spoken chant · a hand shape for every food', '[{"type": "verse", "text": "A pizza hut, a pizza hut,\nFried chicken and a pizza hut.\nA pizza hut, a pizza hut,\nFried chicken and a pizza hut."}, {"type": "verse", "text": "Burger bar, burger bar,\nFried chicken and a pizza hut.\nBurger bar, burger bar,\nFried chicken and a pizza hut."}, {"type": "box", "heading": "The hands", "items": ["**Pizza hut** — draw a roof-shaped triangle in the air.", "**Fried chicken** — flap your elbows like wings.", "**Burger bar** — draw a big “M” with both hands."]}]'::jsonb, 11),
  ('kookaburra-song', 'Kookaburra Song', 'round', 'Round', 'Tune: traditional Australian round · four parts if you''re brave', '[{"type": "verse", "text": "Kookaburra sits in the old gum tree,\nMerry, merry king of the bush is he.\nLaugh, Kookaburra, laugh, Kookaburra,\nGay your life must be."}, {"type": "verse", "text": "Kookaburra sits on an electric wire,\nJumping up and down with his pants on fire.\nOuch, Kookaburra, ouch, Kookaburra,\nHow your tail must hurt."}, {"type": "verse", "text": "Kookaburra sits on a rusty nail,\nGets a boo-boo in his tail.\nCry, Kookaburra, cry, Kookaburra,\nHow life can be cruel."}]'::jsonb, 12),
  ('pirate-song', 'Pirate Song', 'actions', 'Actions', 'Tune: traditional · lean with every direction, faster each verse', '[{"type": "verse", "text": "''Twas a **sunny** day when I went to play,\nDown by the sea.\nI climbed aboard a pirate ship,\nAnd the captain said to me:"}, {"type": "verse", "text": "“We''re going this way, that way,\nForwards, backwards,\nUp and down, up and down,\nOver the deep blue sea.”"}, {"type": "pills", "items": ["windy day", "rainy day", "snowy day", "stormy day"]}, {"type": "note", "text": "Finish by singing the captain''s lines twice through, as fast as you can."}]'::jsonb, 13),
  ('scout-vespers', 'Scout Vespers', 'quiet', 'Quiet', 'Tune: “O Tannenbaum” · the last song, sung standing in a circle', '[{"type": "verse", "text": "Softly falls the light of day,\nWhile our campfire fades away.\nSilently each Scout should ask,\n“Have I done my daily task?"}, {"type": "verse", "text": "Have I kept my honour bright?\nCan I guiltless sleep tonight?\nHave I done and have I dared\nIn everything to be prepared?”"}, {"type": "verse", "text": "Listen, Lord, oh listen, Lord,\nAs I whisper soft and low.\nBless my mum and bless my dad,\nThere is something they should know."}, {"type": "verse", "text": "I have kept my honour bright,\nThe Promise and Law have been my guide.\nMum and Dad, this you should know,\nDeep in my heart I love you so."}]'::jsonb, 14),
  ('baby-shark', 'Baby Shark', 'actions', 'Actions', 'Tune: traditional camp version · alligator hands, one bite per line', '[{"type": "verse", "text": "Baby shark, dut-do dut-dut-dut-do,\nBaby shark, dut-do dut-dut-dut-do,\nBaby shark, dut-do dut-dut-dut-do,\nBaby shark… **UHHHHH!**"}, {"type": "box", "heading": "Repeat with", "items": ["**Mama shark** — alligator with elbows and hands", "**Daddy shark** — alligator with whole arms", "**Grandpa shark** — alligator with fists", "**Hungry shark** — fin on your head, rub your stomach", "**Swimmer** — swim for your life", "**Lost a leg** — hop on one foot", "**Happy shark** — fin on head and a big grin", "**The end** — point at your bottom"]}]'::jsonb, 15),
  ('goin-on-a-bear-hunt', 'Goin'' On A Bear Hunt', 'echo', 'Echo story', 'Spoken · the leader says each line, everyone echoes it back', '[{"type": "verse", "text": "Goin'' on a bear hunt,\nI''m not afraid!\nIt''s a beautiful day,\nThe sun is shining,\nThe birds are singing,\nThe bees are buzzing."}, {"type": "verse", "text": "What''s that? **Tall grass!**\n_Sweep your arms, swish-swish-swish._"}, {"type": "verse", "text": "What''s that? **A tall tree!**\n_Climb all the way up, then back down._"}, {"type": "verse", "text": "What''s that? **Ohh, it''s mud!**\n_March through it — slosh, slosh, slosh._"}, {"type": "verse", "text": "What''s that? **It''s a river!**\nWe''re going to have to swim.\n_Swim hard across it._"}, {"type": "verse", "text": "What''s that? **Ohh, it''s a dark cave…**\n_Drop to a whisper here._"}, {"type": "verse", "text": "I can''t see anything.\nI can feel something.\nI can hear something.\nWe''d better take out our torches.\n_Click it on._"}, {"type": "shout", "text": "Oh — it''s a bear. RUN!"}, {"type": "note", "text": "Chant “I''m not afraid!” between every obstacle. Then back through the cave, the river, the mud, the tree, the grass — in reverse, at top speed."}]'::jsonb, 16),
  ('waltzing-matilda', 'Waltzing Matilda', 'loud', 'Anthem', 'Tune: traditional Australian · chorus after every verse', '[{"type": "verse", "text": "Once a jolly swagman camped by a billabong,\nUnder the shade of a coolibah tree,\nAnd he sang as he watched and waited till his billy boiled,\n“You''ll come a-waltzing Matilda with me.”"}, {"type": "verse", "text": "Waltzing Matilda, Waltzing Matilda,\nYou''ll come a-waltzing Matilda with me,\nAnd he sang as he watched and waited till his billy boiled,\n“You''ll come a-waltzing Matilda with me.”", "label": "Chorus"}, {"type": "verse", "text": "Down came a jumbuck to drink at that billabong,\nUp jumped the swagman and grabbed him with glee,\nAnd he sang as he shoved that jumbuck in his tucker bag,\n“You''ll come a-waltzing Matilda with me.”"}, {"type": "verse", "text": "Up rode the squatter, mounted on his thoroughbred,\nDown came the troopers, one, two, three,\n“Whose that jolly jumbuck you''ve got in your tucker bag?\nYou''ll come a-waltzing Matilda with me.”"}, {"type": "verse", "text": "Up jumped the swagman and sprang into the billabong,\n“You''ll never catch me alive,” said he,\nAnd his ghost may be heard as you pass by that billabong,\n“You''ll come a-waltzing Matilda with me.”"}]'::jsonb, 17),
  ('the-quartermasters-store', 'The Quartermaster''s Store', 'loud', 'Loud', 'Tune: traditional marching song · chorus after every verse', '[{"type": "verse", "text": "There was cheese, cheese, wobbling in the breeze,\nIn the store, in the store.\nThere was cheese, cheese, wobbling in the breeze,\nIn the Quartermaster''s store."}, {"type": "verse", "text": "My eyes are dim, I cannot see,\nI have not brought my specs with me,\nI have not brought my specs with me.", "label": "Chorus"}, {"type": "grid", "heading": "Then swap the cheese for", "items": ["rats, rats, big as blooming cats", "beans, beans, big as submarines", "bread, bread, with great big lumps of lead", "mice, mice, running through the rice", "eggs, eggs, with little wooden legs", "gravy, gravy, enough to sink the navy"]}]'::jsonb, 18),
  ('everywhere-we-go', 'Everywhere We Go', 'echo', 'Echo', 'Shouted echo · leader calls, everyone answers louder', '[{"type": "verse", "text": "Everywhere we go-o, _(echo)_\nPeople want to know-o, _(echo)_\nWho we a-are, _(echo)_\nSo we tell them! _(echo)_"}, {"type": "verse", "text": "We are _(your group)_, _(echo)_\nMighty, mighty _(your group)_! _(echo)_"}, {"type": "note", "text": "And if they can''t hear you — round again, a little louder."}]'::jsonb, 19),
  ('down-by-the-bay', 'Down By The Bay', 'actions', 'Make it up', 'Tune: traditional · everyone takes a turn inventing the last line', '[{"type": "verse", "text": "Down by the bay, where the watermelons grow,\nBack to my home, I dare not go.\nFor if I do, my mother will say:\n“Did you ever see a goose, kissing a moose,\nDown by the bay?”"}, {"type": "box", "heading": "Endings to steal", "items": ["a bear, combing his hair", "a llama, wearing pyjamas", "a whale, with a polka-dot tail", "a snake, baking a cake", "a fly, wearing a tie"]}]'::jsonb, 20),
  ('michael-finnegan', 'Michael Finnegan', 'loud', 'Never ends', 'Tune: traditional · a little faster every single time', '[{"type": "verse", "text": "There was an old man named Michael Finnegan,\nHe grew whiskers on his chinnegan,\nThe wind came out and blew them in again,\nPoor old Michael Finnegan —\n**begin again!**"}, {"type": "note", "text": "There is no last verse. Somebody has to be brave enough to stop it."}]'::jsonb, 21),
  ('black-socks', 'Black Socks', 'round', 'Round', 'Tune: traditional · three-part round, one group in every four beats', '[{"type": "verse", "text": "Black socks, they never get dirty,\nThe longer you wear them the stronger they get.\nSometimes I think I should wash them,\nBut something keeps telling me: don''t do it yet,\nNot yet, not yet, not yet…"}]'::jsonb, 22),
  ('little-peter-rabbit', 'Little Peter Rabbit', 'actions', 'Actions', 'Tune: “Frère Jacques” · drop one word for an action each round', '[{"type": "verse", "text": "Little Peter Rabbit had a fly upon his ear,\nLittle Peter Rabbit had a fly upon his ear,\nLittle Peter Rabbit had a fly upon his ear,\nAnd he flicked it till it flew away."}, {"type": "note", "text": "Round two: no “rabbit” — two fingers up for ears instead. Round three: no “fly” — buzz your finger. Round four: no “flicked” — flick your ear."}]'::jsonb, 23),
  ('day-is-done', 'Day Is Done', 'quiet', 'Last song', 'Tune: “Taps” · almost a whisper, as the coals go orange', '[{"type": "verse", "text": "Day is done, gone the sun,\nFrom the lake, from the hills, from the sky.\nAll is well, safely rest,\nGod is nigh."}, {"type": "verse", "text": "Fading light dims the sight,\nAnd a star gems the sky, gleaming bright.\nFrom afar, drawing nigh,\nFalls the night."}]'::jsonb, 24)
